using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    public static List<string> Categories { get; } = new()
    {
        "Breakfast", "Lunch", "Dinner", "Desserts", "Snacks", "Beverages"
    };

    public static List<Recipe> Recipes { get; } = new()
    {
        new() { Id = 1, Title = "Fluffy Pancakes", Category = "Breakfast", Ingredients = "Flour, Eggs, Milk, Sugar, Baking Powder, Butter", Steps = "1. Mix dry ingredients\n2. Whisk wet ingredients\n3. Combine and cook on griddle", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Classic BLT Sandwich", Category = "Lunch", Ingredients = "Bread, Bacon, Lettuce, Tomato, Mayo", Steps = "1. Toast bread\n2. Cook bacon until crispy\n3. Layer lettuce, tomato, bacon\n4. Spread mayo and serve", AverageRating = 4.0, RatingCount = 8 },
        new() { Id = 3, Title = "Grilled Salmon", Category = "Dinner", Ingredients = "Salmon fillet, Lemon, Garlic, Olive oil, Dill, Salt, Pepper", Steps = "1. Marinate salmon with lemon, garlic, oil\n2. Preheat grill to medium-high\n3. Grill 4-5 min per side\n4. Garnish with dill", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in flour and chocolate mixture\n4. Bake at 425°F for 12 minutes", AverageRating = 4.9, RatingCount = 35 },
        new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks", Ingredients = "Oats, Peanut butter, Honey, Chocolate chips, Flaxseed", Steps = "1. Mix all ingredients\n2. Roll into balls\n3. Refrigerate for 30 minutes", AverageRating = 3.8, RatingCount = 5 },
        new() { Id = 6, Title = "Iced Matcha Latte", Category = "Beverages", Ingredients = "Matcha powder, Milk, Ice, Honey", Steps = "1. Whisk matcha with a small amount of hot water\n2. Fill glass with ice\n3. Pour milk, then matcha\n4. Sweeten with honey", AverageRating = 4.2, RatingCount = 15 },
    };

    private static int _nextId = 7;

    public static void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        Recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = Recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button">
            @(star <= SelectedRating ? "★" : "☆")
        </span>
    }
    @if (ShowCount)
    {
        <span class="rating-info ms-2">(@AverageRating.ToString("0.0") avg, @RatingCount ratings)</span>
    }
</div>

@if (!string.IsNullOrEmpty(Message))
{
    <div class="alert alert-success mt-2 py-1 px-2 d-inline-block">@Message</div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public bool ShowCount { get; set; } = true;

    private int SelectedRating;
    private string? Message;

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeStore.AddRating(RecipeId, stars);
        var recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        Message = $"Thanks! You rated this {stars} star{(stars > 1 ? "s" : "")}.";
    }
}

.star-rating {
    font-size: 1.5rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.2s;
}

.star.filled {
    color: #f5a623;
}

.star:hover {
    color: #f5a623;
}

.rating-info {
    font-size: 0.9rem;
    color: #666;
}

