@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover, share, and rate delicious recipes from our community.</p>
</div>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeStore.Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text text-muted">
                        @RecipeStore.Recipes.Count(r => r.Category == category) recipe(s)
                    </p>
                    <a href="/category/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4 text-center">
    <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Lunch" => "🥪",
        "Dinner" => "🍽️",
        "Desserts" => "🍰",
        "Snacks" => "🍿",
        "Beverages" => "🥤",
        _ => "🍴"
    };
}

arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category yet.</div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeStore.Recipes
            .Where(r => r.Category.Equals(CategoryName, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@recipe?.Title - Recipe Community</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>

    <div class="mb-4">
        <h4>Rate this recipe</h4>
        <StarRating RecipeId="@recipe.Id"
                    AverageRating="@recipe.AverageRating"
                    RatingCount="@recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-5">
            <div class="card mb-3">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-header"><strong>👨‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-1">@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <a href="/category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@newRecipe.Title" has been added.
        <a href="/recipe/@newRecipe.Id">View it here</a>.
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="newRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => newRecipe.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeStore.Categories)
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => newRecipe.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4"
                           @bind-Value="newRecipe.Ingredients"
                           placeholder="Comma-separated list: Flour, Sugar, Butter..." />
            <ValidationMessage For="() => newRecipe.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5"
                           @bind-Value="newRecipe.Steps"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. ..." />
            <ValidationMessage For="() => newRecipe.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">🚀 Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private Recipe newRecipe = new();
    private bool submitted;

    private void HandleSubmit()
    {
        RecipeStore.AddRecipe(newRecipe);
        submitted = true;
    }

    private void Reset()
    {
        newRecipe = new();
        submitted = false;
    }
}

